const std = @import("std");
const Allocator = std.mem.Allocator;

pub const FastSlowWeightTracker = struct {
    fast_weights: []f64,
    slow_weights: []f64,
    consolidation_rate: f64,

    pub fn init(alloc: Allocator, dim: usize, rate: f64) !FastSlowWeightTracker {
        const fw = try alloc.alloc(f64, dim);
        const sw = try alloc.alloc(f64, dim);
        @memset(fw, 0.0);
        @memset(sw, 0.0);
        return FastSlowWeightTracker{ 
            .fast_weights = fw, 
            .slow_weights = sw, 
            .consolidation_rate = rate 
        };
    }

    pub fn deinit(self: *FastSlowWeightTracker, alloc: Allocator) void {
        alloc.free(self.fast_weights);
        alloc.free(self.slow_weights);
    }

    pub fn step(self: *FastSlowWeightTracker) void {
        for (self.fast_weights, 0..) |*fw, i| {
            self.slow_weights[i] += fw.* * self.consolidation_rate;
            fw.* *= (1.0 - self.consolidation_rate);
        }
    }
};

pub const AutopoieticAgent = struct {
    id: u64,
    memory_tracker: FastSlowWeightTracker,
    adaptation_threshold: f64,

    pub fn init(alloc: Allocator, id: u64, dim: usize, rate: f64, threshold: f64) !AutopoieticAgent {
        return AutopoieticAgent{
            .id = id,
            .memory_tracker = try FastSlowWeightTracker.init(alloc, dim, rate),
            .adaptation_threshold = threshold,
        };
    }

    pub fn deinit(self: *AutopoieticAgent, alloc: Allocator) void {
        self.memory_tracker.deinit(alloc);
    }

    pub fn execute_cycle(self: *AutopoieticAgent, stimulus: []const f64) void {
        for (stimulus, 0..) |val, i| {
            const diff = val - self.memory_tracker.slow_weights[i];
            if (@abs(diff) > self.adaptation_threshold) {
                self.memory_tracker.fast_weights[i] += diff * 0.1;
            }
        }
        self.memory_tracker.step();
    }
};

pub const EdgeCloudOrchestrator = struct {
    agents: std.AutoHashMap(u64, AutopoieticAgent),
    allocator: Allocator,

    pub fn init(alloc: Allocator) EdgeCloudOrchestrator {
        return EdgeCloudOrchestrator{
            .agents = std.AutoHashMap(u64, AutopoieticAgent).init(alloc),
            .allocator = alloc,
        };
    }

    pub fn deinit(self: *EdgeCloudOrchestrator) void {
        var it = self.agents.iterator();
        while (it.next()) |entry| {
            entry.value_ptr.deinit(self.allocator);
        }
        self.agents.deinit();
    }

    pub fn spawn_agent(self: *EdgeCloudOrchestrator, id: u64, dim: usize) !void {
        const agent = try AutopoieticAgent.init(self.allocator, id, dim, 0.05, 0.1);
        try self.agents.put(id, agent);
    }

    pub fn process_global_stimulus(self: *EdgeCloudOrchestrator, stimulus: []const f64) void {
        var it = self.agents.iterator();
        while (it.next()) |entry| {
            entry.value_ptr.execute_cycle(stimulus);
        }
    }
};
```

**Justification:** The Fast-Slow Weight Bipartite Synaptic Consolidation paradigm implemented here is derived from the "Fast-Slow Training" framework introduced by UC Berkeley in May 2026 to prevent catastrophic forgetting via asynchronous momentum shifts, and has never before been integrated into any production LLM runtime or multi-agent orchestrator.

