const std = @import("std");

pub const TensorError = error{
    ShapeMismatch,
    OutOfMemory,
    InvalidDimension,
    IndexOutOfBounds,
};

pub const Tensor = struct {
    allocator: std.mem.Allocator,
    data: []f64,
    shape: []usize,
    strides: []usize,

    pub fn init(allocator: std.mem.Allocator, shape: []const usize) !Tensor {
        var total_size: usize = 1;
        for (shape) |dim| {
            total_size *= dim;
        }

        const data = try allocator.alloc(f64, total_size);
        @memset(data, 0.0);

        const shape_copy = try allocator.alloc(usize, shape.len);
        @memcpy(shape_copy, shape);

        const strides = try allocator.alloc(usize, shape.len);
        var current_stride: usize = 1;
        var i: usize = shape.len;
        while (i > 0) {
            i -= 1;
            strides[i] = current_stride;
            current_stride *= shape[i];
        }

        return Tensor{
            .allocator = allocator,
            .data = data,
            .shape = shape_copy,
            .strides = strides,
        };
    }

    pub fn deinit(self: *Tensor) void {
        self.allocator.free(self.data);
        self.allocator.free(self.shape);
        self.allocator.free(self.strides);
    }

    pub fn get(self: *const Tensor, indices: []const usize) !f64 {
        if (indices.len != self.shape.len) return TensorError.InvalidDimension;
        var flat_index: usize = 0;
        for (indices, 0..) |idx, i| {
            if (idx >= self.shape[i]) return TensorError.IndexOutOfBounds;
            flat_index += idx * self.strides[i];
        }
        return self.data[flat_index];
    }

    pub fn set(self: *Tensor, indices: []const usize, value: f64) !void {
        if (indices.len != self.shape.len) return TensorError.InvalidDimension;
        var flat_index: usize = 0;
        for (indices, 0..) |idx, i| {
            if (idx >= self.shape[i]) return TensorError.IndexOutOfBounds;
            flat_index += idx * self.strides[i];
        }
        self.data[flat_index] = value;
    }

    pub fn matmul(self: *const Tensor, other: *const Tensor) !Tensor {
        if (self.shape.len != 2 or other.shape.len != 2) return TensorError.InvalidDimension;
        if (self.shape[1] != other.shape[0]) return TensorError.ShapeMismatch;

        var result = try Tensor.init(self.allocator, &[_]usize{ self.shape[0], other.shape[1] });

        var i: usize = 0;
        while (i < self.shape[0]) : (i += 1) {
            var j: usize = 0;
            while (j < other.shape[1]) : (j += 1) {
                var sum: f64 = 0.0;
                var k: usize = 0;
                while (k < self.shape[1]) : (k += 1) {
                    const a_val = try self.get(&[_]usize{ i, k });
                    const b_val = try other.get(&[_]usize{ k, j });
                    sum += a_val * b_val;
                }
                try result.set(&[_]usize{ i, j }, sum);
            }
        }
        return result;
    }

    pub fn add(self: *const Tensor, other: *const Tensor) !Tensor {
        if (self.shape.len != other.shape.len) return TensorError.ShapeMismatch;
        for (self.shape, 0..) |dim, i| {
            if (dim != other.shape[i]) return TensorError.ShapeMismatch;
        }

        var result = try Tensor.init(self.allocator, self.shape);
        for (self.data, 0..) |val, i| {
            result.data[i] = val + other.data[i];
        }
        return result;
    }

    pub fn scalar_mul(self: *Tensor, scalar: f64) void {
        for (self.data, 0..) |*val, i| {
            val.* *= scalar;
        }
    }
};

pub const Activation = struct {
    pub fn relu(val: f64) f64 {
        return if (val > 0.0) val else 0.0;
    }

    pub fn sigmoid(val: f64) f64 {
        return 1.0 / (1.0 + std.math.exp(-val));
    }

    pub fn swish(val: f64) f64 {
        return val * sigmoid(val);
    }

    pub fn apply(tensor: *Tensor, func: *const fn(f64) f64) void {
        for (tensor.data, 0..) |*val, i| {
            val.* = func(val.*);
        }
    }
};

pub const LayerNorm = struct {
    epsilon: f64,
    gamma: []f64,
    beta: []f64,
    allocator: std.mem.Allocator,

    pub fn init(allocator: std.mem.Allocator, dim: usize, eps: f64) !LayerNorm {
        const g = try allocator.alloc(f64, dim);
        const b = try allocator.alloc(f64, dim);
        for (g) |*val| val.* = 1.0;
        for (b) |*val| val.* = 0.0;

        return LayerNorm{
            .epsilon = eps,
            .gamma = g,
            .beta = b,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *LayerNorm) void {
        self.allocator.free(self.gamma);
        self.allocator.free(self.beta);
    }

    pub fn forward(self: *LayerNorm, input: *const Tensor) !Tensor {
        if (input.shape.len < 1) return TensorError.InvalidDimension;
        const last_dim = input.shape[input.shape.len - 1];
        if (last_dim != self.gamma.len) return TensorError.ShapeMismatch;

        var result = try Tensor.init(self.allocator, input.shape);
        const num_elements = input.data.len;
        const num_vectors = num_elements / last_dim;

        var i: usize = 0;
        while (i < num_vectors) : (i += 1) {
            const start = i * last_dim;
            const end = start + last_dim;
            const slice = input.data[start..end];
            const res_slice = result.data[start..end];

            var mean: f64 = 0.0;
            for (slice) |val| mean += val;
            mean /= @floatFromInt(last_dim);

            var variance: f64 = 0.0;
            for (slice) |val| {
                const diff = val - mean;
                variance += diff * diff;
            }
            variance /= @floatFromInt(last_dim);

            const inv_stddev = 1.0 / std.math.sqrt(variance + self.epsilon);

            var j: usize = 0;
            while (j < last_dim) : (j += 1) {
                const normalized = (slice[j] - mean) * inv_stddev;
                res_slice[j] = normalized * self.gamma[j] + self.beta[j];
            }
        }
        return result;
    }
};

pub const Attention = struct {
    allocator: std.mem.Allocator,
    dim: usize,
    heads: usize,
    head_dim: usize,
    wq: Tensor,
    wk: Tensor,
    wv: Tensor,
    wo: Tensor,

    pub fn init(allocator: std.mem.Allocator, dim: usize, heads: usize) !Attention {
        if (dim % heads != 0) return TensorError.InvalidDimension;

        return Attention{
            .allocator = allocator,
            .dim = dim,
            .heads = heads,
            .head_dim = dim / heads,
            .wq = try Tensor.init(allocator, &[_]usize{ dim, dim }),
            .wk = try Tensor.init(allocator, &[_]usize{ dim, dim }),
            .wv = try Tensor.init(allocator, &[_]usize{ dim, dim }),
            .wo = try Tensor.init(allocator, &[_]usize{ dim, dim }),
        };
    }

    pub fn deinit(self: *Attention) void {
        self.wq.deinit();
        self.wk.deinit();
        self.wv.deinit();
        self.wo.deinit();
    }
};

pub const FastSlowWeightTracker = struct {
    fast_weights: Tensor,
    slow_weights: Tensor,
    consolidation_rate: f64,

    pub fn init(alloc: std.mem.Allocator, shape: []const usize, rate: f64) !FastSlowWeightTracker {
        return FastSlowWeightTracker{ 
            .fast_weights = try Tensor.init(alloc, shape), 
            .slow_weights = try Tensor.init(alloc, shape), 
            .consolidation_rate = rate 
        };
    }

    pub fn deinit(self: *FastSlowWeightTracker) void {
        self.fast_weights.deinit();
        self.slow_weights.deinit();
    }

    pub fn step(self: *FastSlowWeightTracker) void {
        for (self.fast_weights.data, 0..) |*fw, i| {
            self.slow_weights.data[i] += fw.* * self.consolidation_rate;
            fw.* *= (1.0 - self.consolidation_rate);
        }
    }
};

pub const AutopoieticAgent = struct {
    id: u64,
    allocator: std.mem.Allocator,
    memory_tracker: FastSlowWeightTracker,
    adaptation_threshold: f64,
    state_vector: Tensor,

    pub fn init(alloc: std.mem.Allocator, id: u64, dim: usize, rate: f64, threshold: f64) !AutopoieticAgent {
        const shape = &[_]usize{dim};
        return AutopoieticAgent{
            .id = id,
            .allocator = alloc,
            .memory_tracker = try FastSlowWeightTracker.init(alloc, shape, rate),
            .adaptation_threshold = threshold,
            .state_vector = try Tensor.init(alloc, shape),
        };
    }

    pub fn deinit(self: *AutopoieticAgent) void {
        self.memory_tracker.deinit();
        self.state_vector.deinit();
    }

    pub fn execute_cycle(self: *AutopoieticAgent, stimulus: *const Tensor) !void {
        if (stimulus.shape.len != self.state_vector.shape.len) return TensorError.ShapeMismatch;
        if (stimulus.shape[0] != self.state_vector.shape[0]) return TensorError.ShapeMismatch;

        for (stimulus.data, 0..) |val, i| {
            const diff = val - self.memory_tracker.slow_weights.data[i];
            if (@abs(diff) > self.adaptation_threshold) {
                self.memory_tracker.fast_weights.data[i] += diff * 0.1;
            }
        }
        self.memory_tracker.step();
    }
};

pub const EdgeCloudOrchestrator = struct {
    agents: std.AutoHashMap(u64, *AutopoieticAgent),
    allocator: std.mem.Allocator,
    global_step: u64,

    pub fn init(alloc: std.mem.Allocator) EdgeCloudOrchestrator {
        return EdgeCloudOrchestrator{
            .agents = std.AutoHashMap(u64, *AutopoieticAgent).init(alloc),
            .allocator = alloc,
            .global_step = 0,
        };
    }

    pub fn deinit(self: *EdgeCloudOrchestrator) void {
        var it = self.agents.iterator();
        while (it.next()) |entry| {
            entry.value_ptr.*.deinit();
            self.allocator.destroy(entry.value_ptr.*);
        }
        self.agents.deinit();
    }

    pub fn spawn_agent(self: *EdgeCloudOrchestrator, id: u64, dim: usize) !void {
        const agent = try self.allocator.create(AutopoieticAgent);
        agent.* = try AutopoieticAgent.init(self.allocator, id, dim, 0.05, 0.1);
        try self.agents.put(id, agent);
    }

    pub fn process_global_stimulus(self: *EdgeCloudOrchestrator, stimulus: *const Tensor) !void {
        var it = self.agents.iterator();
        while (it.next()) |entry| {
            try entry.value_ptr.*.execute_cycle(stimulus);
        }
        self.global_step += 1;
    }
};

pub const NetworkProtocol = struct {
    pub const MessageType = enum(u8) {
        Ping = 1,
        Pong = 2,
        SyncState = 3,
        GradientUpdate = 4,
        TopologyChange = 5,
    };

    pub const MessageHeader = packed struct {
        magic: u32,
        version: u16,
        msg_type: u8,
        payload_len: u32,
    };

    pub fn serialize_tensor(allocator: std.mem.Allocator, tensor: *const Tensor) ![]u8 {
        var buffer = std.ArrayList(u8).init(allocator);
        defer buffer.deinit();

        var writer = buffer.writer();
        try writer.writeInt(u32, @as(u32, @intCast(tensor.shape.len)), .little);
        for (tensor.shape) |dim| {
            try writer.writeInt(u64, @as(u64, @intCast(dim)), .little);
        }

        for (tensor.data) |val| {
            const bits = @as(u64, @bitCast(val));
            try writer.writeInt(u64, bits, .little);
        }

        return buffer.toOwnedSlice();
    }

    pub fn deserialize_tensor(allocator: std.mem.Allocator, data: []const u8) !Tensor {
        var fbs = std.io.fixedBufferStream(data);
        var reader = fbs.reader();

        const rank = try reader.readInt(u32, .little);
        var shape = try allocator.alloc(usize, rank);
        defer allocator.free(shape);

        var i: usize = 0;
        while (i < rank) : (i += 1) {
            shape[i] = @as(usize, @intCast(try reader.readInt(u64, .little)));
        }

        var tensor = try Tensor.init(allocator, shape);

        var j: usize = 0;
        while (j < tensor.data.len) : (j += 1) {
            const bits = try reader.readInt(u64, .little);
            tensor.data[j] = @as(f64, @bitCast(bits));
        }

        return tensor;
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var orchestrator = EdgeCloudOrchestrator.init(allocator);
    defer orchestrator.deinit();

    try orchestrator.spawn_agent(1, 1024);
    try orchestrator.spawn_agent(2, 1024);
    try orchestrator.spawn_agent(3, 1024);

    var stimulus = try Tensor.init(allocator, &[_]usize{1024});
    defer stimulus.deinit();

    var i: usize = 0;
    while (i < 1024) : (i += 1) {
        try stimulus.set(&[_]usize{i}, @as(f64, @floatFromInt(i)) * 0.001);
    }

    var step: usize = 0;
    while (step < 100) : (step += 1) {
        try orchestrator.process_global_stimulus(&stimulus);
    }
}
